// ── Parse & normalise the payload from Tough Tongue AI ──────────────────
// Tough Tongue AI sends tool arguments inside a 'parameters' or 'arguments' key.
// Adjust the field names below if their payload shape differs.
const body = $input.first().json.body ?? $input.first().json;

// Expected fields from the AI conversation:
const patientName   = body.patient_name   ?? body.patientName   ?? 'Unknown Patient';
const patientPhone  = body.patient_phone  ?? body.patientPhone  ?? '';
const requestedDate = body.requested_date ?? body.requestedDate ?? '';
// e.g. '2026-09-10'
const requestedTime = body.requested_time ?? body.requestedTime ?? '';
// e.g. '14:00'  (24-hr, IST)

// Build ISO 8601 start/end datetimes in IST (UTC+5:30)
// Appointment duration: 30 minutes (change as needed)
const startIST = `${requestedDate}T${requestedTime}:00+05:30`;
const [h, m] = requestedTime.split(':').map(Number);
const endMinutes = m + 30;
const endH = String(h + Math.floor(endMinutes / 60)).padStart(2, '0');
const endM = String(endMinutes % 60).padStart(2, '0');
const endIST   = `${requestedDate}T${endH}:${endM}:00+05:30`;

return [{
  json: {
    patientName,
    patientPhone,
    requestedDate,
    requestedTime,
    startIST,
    endIST
  }
}];

