// ── Find next available 30-min slot (searches up to 8 slots ahead) ───────
const input = $('Parse & Normalise Input').first().json;
const busyBlocks = $input.first().json.calendars[process.env.GOOGLE_CALENDAR_ID ?? $vars.GOOGLE_CALENDAR_ID]?.busy ?? [];

// Parse requested start
let candidateMs = new Date(input.startIST).getTime();
const slotMs = 30 * 60 * 1000; // 30 minutes
const clinicEndHour = 18; // clinic closes at 6 PM IST — adjust as needed

for (let i = 0; i < 8; i++) {
  const candidateStart = new Date(candidateMs);
  const candidateEnd   = new Date(candidateMs + slotMs);

  // Stop searching past clinic closing time
  if (candidateStart.getHours() >= clinicEndHour) {
    return [{ json: { slotFound: false, message: 'No slots available today after this time.' } }];
  }

  const isBusy = busyBlocks.some(block => {
    const bStart = new Date(block.start).getTime();
    const bEnd   = new Date(block.end).getTime();
    // Overlap check
    return candidateMs < bEnd && (candidateMs + slotMs) > bStart;
  });

  if (!isBusy) {
    const pad = n => String(n).padStart(2, '0');
    const hh = pad(candidateStart.getHours());
    const mm = pad(candidateStart.getMinutes());
    return [{ json: {
      slotFound: true,
      suggestedTime: `${hh}:${mm}`,
      suggestedStartIST: candidateStart.toISOString().replace('Z', '+05:30'),
      suggestedEndIST:   candidateEnd.toISOString().replace('Z', '+05:30'),
      patientName:  input.patientName,
      patientPhone: input.patientPhone
    }}];
  }

  candidateMs += slotMs; // try the next 30-min window
}

return [{ json: { slotFound: false, message: 'No slots available in the next 4 hours.' } }];

